// Text catalog access. Texts come from resources/ and are generated by `just gen`.
// Never hard-code UI text in templates.

/// Looks up a COPY key and fills `{name}` placeholders. Unknown keys return the key itself.
public func t(_ key: String, _ vars: [String: String] = [:]) -> String {
    guard var text = CopyTable.active[key] else { return key }
    for (name, value) in vars {
        text = text.replacingOccurrences(of: "{\(name)}", with: value)
    }
    return text
}

public func t(_ key: String, _ vars: [String: Int]) -> String {
    t(key, vars.mapValues(String.init))
}
